from pathlib import Path
import json, html, zipfile
from xml.sax.saxutils import escape
from openpyxl import load_workbook
P=Path(__file__).resolve().parent
v=json.loads((P/'results.json').read_text());research=json.loads((P/'research.json').read_text());wb=load_workbook(P/'model.xlsx',data_only=True)
paragraphs=[]
def add(title,text):paragraphs.extend([(title,True),(text,False)])
add('PROJECT XL — executive investment report','Student housing near VUB, Brussels | Prepared 14 October 2026. Screening model for a hypothetical site. No actual property, investor budget, construction quotation or student-income survey was provided. The EUR5 million total budget and EUR3.25 million equity limit are assumptions, not user commitments.')
add('Decision','Conditional feasibility, but do not commit on these assumptions: 40 rooms maximise year-one equity cash flow within the assumed capital, equity, site capacity and debt-service constraints. They cost EUR4,960,400, funded by EUR3,224,260 equity and EUR1,736,140 debt. The 3.27% net operating yield misses the assumed 4.5% target. Financial screening does not establish planning or rent-law compliance.')
add('What “rent threshold” means','There is no universal Brussels student rent cap. Use three separate tests: an actual student housing budget; comparable private-room rents; and the reference-rent/excessive-rent framework for the exact dwelling. Regional guidance requires disclosure of reference rent and prohibits excessive rent from 1 May 2025. More than 20% above reference creates a rebuttable presumption; defects can also make lower rents excessive. Therefore reference × 1.20 is not automatic permission to charge that amount. Confirm how the calculator treats the proposed student/shared accommodation.')
add('Concrete affordability proposal','Bru Kot’s current Brussels listing statistics show a student-room median of EUR500 excluding charges and EUR590 including charges; all accommodation types have medians of EUR550 and EUR650. These are asking/listing benchmarks, not signed rents or a VUB-neighbourhood valuation. Set proposed base rent to EUR475 and charges to EUR100: EUR575 all-in, below both room medians and an assumed EUR600 student budget. The workbook’s EUR500 reference-rent planning ceiling is UNVERIFIED and must be replaced. A student-budget cap must be established by surveying resources and other living costs; no universal affordable share is asserted.')
add('VUB comparison','VUB’s standard room is EUR449.30 per month all-in for 2026–27, including energy, internet, fire insurance and communal maintenance. The proposal is EUR125.70/month more expensive. Thus EUR575 is below the private-room benchmark but does not match VUB affordability or serve every low-income student. Eligibility and limited supply constrain access to VUB housing. The Scenarios sheet tests matching EUR449.30 all-in, using EUR349.30 base rent with EUR100 charges; this reduces financial viability.')
add('Worked capital calculation','40 rooms × 34 gross m² per room = 1,360 m². Construction: 1,360 × EUR2,400 = EUR3,264,000. Furniture: 40 × EUR5,000 = EUR200,000. Contingency: 10% × (construction + furniture) = EUR346,400. Add assumed land purchase EUR900,000 and fixed acquisition/professional/permit costs EUR250,000: total EUR4,960,400. Construction rates are assumed VAT-inclusive. Confirm VAT treatment, registration/notary costs and fee breakdown to prevent omitted costs or double counting. This is a land-and-development example; do not apply it unchanged to an existing building purchase.')
add('Worked operating return','Potential annual base rent = 40 × EUR475 × 12 = EUR228,000. At 95% occupancy/collection, revenue is EUR216,600. Assumed operating expenses and reserve provision are 25%, EUR54,150, leaving EUR162,450 net operating income. EUR100 charges are treated as a cost-recovery pass-through with no investor profit; independently validate utilities and reconciliations. NOI / total investment = 3.27%. These are nominal forecasts before investor income tax, not guaranteed returns.')
add('Finance and capital recovery','Assume 35% debt at 4.5% fixed interest, amortised over 25 operating years: annual principal and interest EUR117,084. Equity cash flow is EUR45,366/year, a 1.41% initial cash-on-cash return; debt-service coverage is 1.39 against an assumed lender minimum of 1.20. Without rent/cost growth, project-cost payback is 30.53 operating years plus two development years = 32.53 years. With assumed 2% rent growth and 2.5% cost growth, cumulative project cash flow turns nonnegative in year 27 and cumulative equity cash flow in year 32, both measured from investment. Static equity payback of 73.07 years freezes year-one debt service indefinitely and is only a screening ratio; use the dynamic equity schedule, which ends debt payments after 25 operating years. All investment is assumed paid at time zero; no sale proceeds or terminal property value are included.')
add('NPV and interpretation',f"At a 6% unlevered discount rate, 30 operating years and no terminal value, project NPV is EUR{v['NPV excluding terminal value']:,.0f}; corresponding operating-only IRR is {v['IRR excluding terminal value']:.2%}. This omission of terminal property value is material; these values do not measure a total-return strategy including an eventual sale.")
lines=[]
for n in [12,24,36,40,41,48]:
 r=n-10;row=[wb['Room sizing'].cell(r,c).value for c in range(1,12)]
 lines.append(f"{n} rooms: total EUR{row[2]:,.0f}; equity EUR{row[3]:,.0f}; NOI EUR{row[4]:,.0f}; equity CF EUR{row[6]:,.0f}; yield {row[7]:.2%}; DSCR {row[8]:.2f}; feasible {row[9]}.")
add('How many rooms, and minimum meaningful capital','Every integer room count from 12 to 96 is evaluated, with an assumed site maximum of 60. Feasibility requires total investment ≤ EUR5m, equity ≤ EUR3.25m, positive equity cash flow and DSCR ≥ 1.20. The smallest qualifying size is 24 rooms, costing EUR3,436,240 and requiring EUR2,233,556 equity. “Meaningful” here means lender-and-budget feasibility; it does not meet the 4.5% return target. The best candidate is 40 rooms; 41 exceeds the budget. Neither a true site optimum nor planning capacity can be established without a site.\n'+'\n'.join(lines))
add('What must change to meet the target','At 40 rooms and EUR475 rent, the maximum all-in cost compatible with a 4.5% net yield is EUR162,450 / 4.5% = EUR3,610,000. Reduce project cost by EUR1,350,400 (27.2%), obtain grant/land support that genuinely lowers net invested capital, or lower the target. Holding costs fixed would require base rent EUR652.68, plus charges, which exceeds the chosen affordability and market limits. Raising rent is therefore not the recommended solution. Increasing room count alone does not meet 4.5% with the current variable cost and rent assumptions.')
add('Stress tests','The Scenarios sheet recalculates downside/base/upside and VUB-affordability cases using capped rents. Downside: EUR400 base rent, 90% occupancy and 15% higher total costs. Upside: EUR500, 98% occupancy and 5% lower costs. A reduction to ten collected months lowers baseline yield to 2.73%; this tests lost collections/early departures rather than asserting a ten-month standard lease. Interest, leverage, costs, student budget and occupancy are editable. Major repairs beyond the operating reserve, cost overruns, tax and development financing can reduce cash flow.')
add('Steps to follow','1. Define actual equity, debt access, return target and student all-in budget through a survey.\n2. Identify a site near VUB; check title, planning use, capacity, layout and fire/accessibility requirements with an architect and municipality. From January 2026, regional guidance states a 12 m² minimum net surface for student accommodation; meeting this single rule does not establish complete compliance. The model assumes 18 m² private room and 34 m² gross project allocation.\n3. Collect current comparable rooms in the VUB catchment with a consistent rent/charges split; obtain the exact dwelling reference and legal assessment.\n4. Obtain itemised acquisition, construction, tax, utilities, maintenance and professional-fee quotes; enter them in Inputs. Confirm reserve adequacy and development interest treatment.\n5. Obtain a lender term sheet; test debt-service coverage and cash-flow reserves during development and occupancy ramp-up.\n6. Re-run room sizing and scenarios. Approve only when affordability, planning, legal rent, budget and return target all pass.\n7. Prepare student leases, EPB documentation, registration and operations before letting. Track actual rent, vacancy and expenses against the model.')
add('How to use and reproduce the deliverables','Open model.xlsx; blue cells on Inputs are editable, formulas recalculate in Excel. The file also includes cached baseline results for viewers. Investment gives returns and payback; Annual cash flow separates project and equity flows; Room sizing searches feasible room counts; Scenarios stress-tests; Sources records links and assumptions. Run python3 build_model.py then python3 cache_model.py then python3 build_report.py to regenerate. Openpyxl is required. Report figures describe the saved baseline; regenerate the report after changing workbook assumptions. Cash-flow horizon supports 1–38 operating years.')
add('Sources and limitations','All sources accessed 14 October 2026. Property, costs, lender terms and student budget remain unverified.\n'+'\n'.join(f'{r[0]}: {r[1]}\n{r[2]}' for r in research['sources']))
body=''.join(f'<h2>{html.escape(t)}</h2>' if heading else '<p>'+html.escape(t).replace('\n','<br>')+'</p>' for t,heading in paragraphs)
(P/'executive_report.html').write_text('<!doctype html><html><head><meta charset="utf-8"><title>PROJECT XL executive report</title><style>body{font:15px/1.5 Arial;max-width:960px;margin:40px auto;color:#172b4d}h2{color:#17365d}p{margin-bottom:22px}@media print{body{margin:15mm;font-size:11pt}}</style></head><body>'+body+'</body></html>')
# Standalone Word report, built without external document libraries.
wp=[]
for t,heading in paragraphs:
 for line in t.split('\n'):
  wp.append('<w:p><w:r>'+('<w:rPr><w:b/><w:sz w:val="28"/></w:rPr>' if heading else '')+'<w:t xml:space="preserve">'+escape(line)+'</w:t></w:r></w:p>')
document='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'+''.join(wp)+'<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134"/></w:sectPr></w:body></w:document>'
with zipfile.ZipFile(P/'executive_report.docx','w',zipfile.ZIP_DEFLATED) as z:
 z.writestr('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>')
 z.writestr('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>')
 z.writestr('word/document.xml',document)
print('Executive report saved in Word and HTML formats.');print('SAVE_NOW:',(P/'SAVE_NOW.txt').exists())
